import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

const matrix = JSON.parse(
  await readFile(
    new URL("../integrations/chatgpt/tool-annotations.json", import.meta.url),
    "utf8",
  ),
);
const target = new URL(
  "../integrations/chatgpt/tool-annotations.md",
  import.meta.url,
);
const keys = [
  "readOnlyHint",
  "destructiveHint",
  "openWorldHint",
  "idempotentHint",
];
const lines = [
  `# Justification des annotations MCP — candidat du ${matrix.reviewedOn}`,
  "",
  "<!-- Generated by scripts/build-mcp-annotation-docs.mjs; edit tool-annotations.json. -->",
  "",
  `Cette matrice couvre les **${matrix.tools.length} outils** du candidat local, avec`,
  "tous les services facultatifs raccordés. Elle décrit le comportement de",
  "production autorisé, y compris les effets indirects ; les restrictions du",
  "compte reviewer ne redéfinissent pas les capacités générales des outils.",
  "Elle ne prouve ni le catalogue déployé, ni celui enregistré dans le portail,",
  "ni les valeurs réellement examinées pour la version rejetée 0.3.2.",
  "",
  "Source structurée : [tool-annotations.json](tool-annotations.json).",
  "Ce JSON est une matrice interne de preuves, pas un formulaire officiel",
  "d’import OpenAI. Le [dossier de remédiation](../../docs/MCP_ANNOTATION_REMEDIATION.md)",
  "distingue les corrections locales, leurs tests et les vérifications restantes.",
  "",
  "## Règles appliquées",
  "",
  "Les quatre annotations sont des booléens explicites. Les trois premières sont",
  "requises par OpenAI ; l’idempotence est facultative dans la référence, mais",
  "Guteneo la déclare et la justifie également pour chaque outil.",
  "",
  "Après succès validé, le wrapper peut persister l’activité d’une connexion de",
  "production autorisée. Cette écriture change un état de connexion visible ;",
  "`readOnlyHint=false` et `idempotentHint=false` décrivent donc le contrat",
  "complet, même quand l’opération métier ne fait que lire. Les clés métier",
  "continuent d’empêcher la duplication des opérations qu’elles protègent.",
  "",
  "Le marqueur destructif couvre aussi les révocations et les effets irréversibles",
  "indirects. Une connexion réseau vers un compte privé borné ne suffit pas à",
  "rendre un outil open-world. Les descriptions et justifications ne remplacent",
  "jamais scopes, rôles, mandats, contrôles serveur ou confirmations de l’hôte.",
  "",
  "Les pages officielles divergent sur l’obligation de fournir les justifications.",
  "La notice de refus fournie le 20 octobre les demande explicitement : chaque",
  "valeur est donc justifiée ci-dessous, sans déduire une dispense d’une autre page.",
  "",
  ...matrix.policySources.map(
    ({ url }) => `- [Documentation officielle OpenAI](${url})`,
  ),
  "",
  "## Vérification reproductible",
  "",
  "Exécuter `npm run audit:mcp` : découverte `tools/list` par le transport MCP du",
  "SDK, vérification de la couverture exacte, des booléens, des justifications",
  "et des références de code. Aucun handler métier n’est appelé.",
  "Le contrôle ne remplace pas l’audit sémantique des handlers ni le scan du",
  "serveur déployé dans le portail. `node scripts/build-mcp-annotation-docs.mjs",
  "--check` vérifie que ce document correspond exactement à la matrice.",
  "",
  "## Valeurs par outil",
  "",
  "| Outil | readOnlyHint | destructiveHint | openWorldHint | idempotentHint |",
  "| --- | --- | --- | --- | --- |",
  ...matrix.tools.map(
    (tool) =>
      `| \`${tool.name}\` | ${keys.map((key) => `\`${tool.annotations[key]}\``).join(" | ")} |`,
  ),
  "",
  "## Justifications et sources",
  "",
];
for (const tool of matrix.tools) {
  lines.push(`### \`${tool.name}\``, "");
  for (const key of keys) {
    lines.push(
      `- **\`${key}: ${tool.annotations[key]}\`** — ${tool.justification[key]}`,
    );
  }
  lines.push(
    "",
    `Preuves : ${tool.evidence.map(({ path, symbol }) => `[\`${symbol.replaceAll("`", "")}\`](../../${path})`).join(", ")}.`,
    "",
  );
}
const contents = `${lines.join("\n").trimEnd()}\n`;
if (process.argv.slice(2).some((arg) => arg !== "--check"))
  throw new Error(
    "Usage: node scripts/build-mcp-annotation-docs.mjs [--check]",
  );
if (process.argv.includes("--check")) {
  if ((await readFile(target, "utf8")) !== contents)
    throw new Error(
      `Outdated annotation documentation: run node scripts/build-mcp-annotation-docs.mjs (${fileURLToPath(target)}).`,
    );
  console.log(
    `Annotation documentation synchronized: ${matrix.tools.length} tools.`,
  );
} else {
  await writeFile(target, contents);
  console.log(
    `Generated annotation documentation: ${matrix.tools.length} tools.`,
  );
}
